#define _GNU_SOURCE
#include <sched.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/utsname.h>
#include <errno.h>
#include <string.h>

void show_hostname(const char *label) {
    struct utsname uts;
    if (uname(&uts) == 0) {
        printf("%s: Hostname = %s\n", label, uts.nodename);
    } else {
        perror("uname");
    }
}

int main() {
    const char *new_hostname = "isolated-ns-host";
    // Request a new UTS namespace (hostname/domain isolation)
    int flags = CLONE_NEWUTS;

    // 1. Show original hostname
    show_hostname("Before unshare");

    // 2. Unshare the UTS namespace
    if (unshare(flags) == -1) {
        if (errno == EPERM) {
            fprintf(stderr, "Error: unshare failed (EPERM). Requires CAP_SYS_ADMIN.\n");
        } else {
            perror("unshare failed");
        }
        return EXIT_FAILURE;
    }

    printf("Successfully unshared UTS namespace.\n");

    // 3. Set a new hostname, which only affects this isolated namespace
    if (sethostname(new_hostname, strlen(new_hostname)) == -1) {
        perror("sethostname failed");
    } else {
        printf("New hostname set to: %s\n", new_hostname);
    }

    // 4. Show hostname inside the new namespace
    show_hostname("After sethostname");

    return EXIT_SUCCESS;
}
